<template><div class="login-page"><form class="login-card" @submit.prevent="login"><div class="brand"><span class="brand-mark">WN</span><span><b>WON NYACI RUN</b><small>CMS 2026</small></span></div><span class="login-kicker">CONTROL ROOM</span><h1>Welcome back.</h1><p>Manage stories, messages, payment instructions and X synchronization from one place.</p><div v-if="error" class="error">{{error}}</div><div class="field"><label>Email</label><input v-model="email" type="email" autocomplete="username" required></div><div class="field"><label>Password</label><input v-model="password" type="password" autocomplete="current-password" required></div><button class="btn btn-primary" :disabled="loading">{{loading?'Signing in…':'Enter dashboard →'}}</button></form></div></template>
<script setup>import {ref} from 'vue';import {useRouter} from 'vue-router';import axios from 'axios';const router=useRouter(),email=ref(''),password=ref(''),error=ref(''),loading=ref(false);const login=async()=>{loading.value=true;try{await axios.get('/api/csrf');await axios.post('/api/admin/login',{email:email.value,password:password.value});router.push('/admin')}catch(e){error.value=e.response?.data?.message||'Login failed'}finally{loading.value=false}}</script>
